import torch
import torch.nn as nn
import torch.utils.cpp_extension as cpp

# CUDA source implementing half‑precision MSE with float32 accumulation
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const __half* __restrict__ pred,
                           const __half* __restrict__ target,
                           float* __restrict__ sum,
                           size_t N) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    float thread_sum = 0.0f;
    // grid‑stride loop
    for (size_t i = idx; i < N; i += blockDim.x * gridDim.x) {
        __half a = pred[i];
        __half b = target[i];
        float diff = __half2float(a) - __half2float(b);
        thread_sum += diff * diff;
    }
    // block reduction in shared memory
    __shared__ float shmem[256];          // assumes blockDim.x <= 256
    int lane = threadIdx.x;
    shmem[lane] = thread_sum;
    __syncthreads();

    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (lane < offset) {
            shmem[lane] += shmem[lane + offset];
        }
        __syncthreads();
    }
    // write block result atomically
    if (lane == 0) {
        atomicAdd(sum, shmem[0]);
    }
}

// Wrapper called from Python
torch::Tensor mse_forward(torch::Tensor pred, torch::Tensor target) {
    TORCH_CHECK(pred.is_cuda() && target.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(pred.scalar_type() == at::kHalf && target.scalar_type() == at::kHalf,
                "inputs must be torch.float16");
    TORCH_CHECK(pred.sizes() == target.sizes(),
                "predictions and targets must have the same shape");

    size_t N = pred.numel();
    // device scalar for the sum (float32)
    auto sum = torch::zeros({1}, torch::device(pred.device()).dtype(at::kFloat));

    const int threads = 256;
    // cap number of blocks to a reasonable size for A100
    const int max_blocks = 65535;
    int blocks = static_cast<int>((N + threads - 1) / threads);
    if (blocks > max_blocks) blocks = max_blocks;

    dim3 grid(blocks);
    dim3 block(threads);

    mse_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(pred.data_ptr()),
        reinterpret_cast<const __half*>(target.data_ptr()),
        sum.data_ptr<float>(),
        N
    );
    cudaDeviceSynchronize();

    float total = sum.item<float>();
    float mean = total / static_cast<float>(N);
    // return a half‑scalar tensor to match torch.mean's dtype for half inputs
    return torch::full({1},
                       static_cast<at::Half>(mean),
                       torch::device(pred.device()).dtype(at::kHalf));
}

// Bind the function for Python
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mse_forward", &mse_forward, "Half‑precision MSE forward (CUDA)");
}
'''

# Build the inline extension
mse_ext = cpp.load_inline(name='mse_ext',
                          cpp_sources='',
                          cuda_sources=cuda_src,
                          functions=['mse_forward'],
                          verbose=False)

# PyTorch model that uses the custom kernel
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, predictions, targets):
        return mse_ext.mse_forward(predictions, targets)

# Helper to create inputs (identical to reference)
def get_inputs():
    scale = torch.rand(())
    return [torch.rand(32768, 32768, dtype=torch.float16, device='cuda') * scale,
            torch.rand(32768, 32768, dtype=torch.float16, device='cuda')]

def get_init_inputs():
    return []
